text:
{
  "headline": "Lidocaine injection shortage stems from long‑standing FDA regulatory actions at multiple manufacturers; Corvale East can transfer 204 units to Corvale Lakeside to cover immediate needs.",
  "headline_cites": ["E76", "E66", "E67", "E68", "E69", "E70", "E71", "E72", "E73", "E74", "E75", "D1", "D3"],
  "sentences": [
    {
      "text": "FDA first posted the lidocaine hydrochloride injection shortage on 2012-02-22 and it remains current as of 2026-10-21.",
      "cites": ["E76", "E66"]
    },
    {
      "text": "The shortage affects multiple manufacturers including Amphastar Pharmaceuticals, Anthea Pharma, B. Braun Medical, Baxter Healthcare, Eugia US, Fresenius Kabi USA, Hikma Pharmaceuticals USA, Hospira, Huons, and Spectra Medical Devices.",
      "cites": ["E66", "E67", "E68", "E69", "E70", "E71", "E72", "E73", "E74", "E75"]
    },
    {
      "text": "FDA records show a Warning Letter issued to Fresenius Kabi USA, LLC on 2012-02-22, the same day the shortage was posted.",
      "cites": ["E48", "E76"]
    },
    {
      "text": "Fresenius Kabi USA, LLC received OAI classifications after inspections ending 2011-07-08, 2011-08-04, 2013-01-11, 2020-05-18, and 2022-06-30.",
      "cites": ["E39", "E14", "E41", "E33", "E34"]
    },
    {
      "text": "Hospira, Inc. received a Warning Letter on 2010-04-12 and OAI classifications after inspections ending 2010-01-19, 2011-06-17, and 2011-08-04.",
      "cites": ["E60", "E53", "E54", "E55"]
    },
    {
      "text": "Corvale East holds 357 packages of Hikma lidocaine (NDC 00143957510) with 18.9 daily use, providing 19 days on hand.",
      "cites": ["E1", "D1"]
    },
    {
      "text": "Corvale Lakeside holds only 4 days of supply, and transferring 204 units from Corvale East would give Lakeside 14 days while East retains a two‑week buffer.",
      "cites": ["D3", "D1"]
    }
  ]
}
